import {readFileSync,writeFileSync} from 'node:fs';
const r=JSON.parse(readFileSync('release/grub-plan-nutrition-review-20261023.json','utf8')),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=n=>n===null||n===undefined?'Unknown':Number(n).toLocaleString('en-GB',{maximumFractionDigits:1});
const recipes=new Map(r.exampleRecipes.map(x=>[x.id,x]));
const table=(headers,rows)=>'<table><thead><tr>'+headers.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
const coverage=table(['Recorded nutrient','Known recipes','Unknown recipes'],Object.entries(r.productionCatalogue.coverage).map(([key,v])=>[esc(key.replaceAll('_',' ')),num(v.known),num(v.unknown)]));
const matrix=table(['Style / 450 days','Energy range (kcal/person)','Days with unknown fibre'],r.matrix.styles.map(s=>[esc(s.style),num(s.kcal.min)+'–'+num(s.kcal.max),num(s.fibreGrams.unknown)]));
const cases=r.examples.map(ex=>'<section><h2>'+esc(ex.style)+' · seven-day example</h2><p>Two people eating; estimates below are for one person. These are three meal ideas per day and exclude snacks, drinks and other food.</p>'+table(['Day','Actual recipes','Recorded estimates per person'],ex.nutrition.days.map(d=>[num(d.day),ex.week.filter(e=>e.day===d.day).map(e=>'<div>'+esc(e.slot)+': <a href="#'+esc(e.recipeId)+'">'+esc(recipes.get(e.recipeId).name)+'</a></div>').join(''),num(d.kcal)+' kcal<br>'+num(d.protein)+'g protein<br>'+(d.fibre===null?'Fibre unknown':num(d.fibre)+'g fibre')]))+'</section>').join('');
const details=r.exampleRecipes.map(x=>'<details id="'+esc(x.id)+'"><summary>'+esc(x.name)+'</summary><p>Recipe ID: <code>'+esc(x.id)+'</code><br>Original recipe serves '+esc(x.servings)+'. Nutrition below is per person; cooking quantities serve the original recipe.</p><h3>Ingredients</h3><ul>'+x.ingredients.map(i=>'<li>'+esc([i.amount,i.unit,i.item].filter(Boolean).join(' '))+'</li>').join('')+'</ul><h3>Method</h3><ol>'+x.method.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ol><p>Equipment: '+esc((x.equipment||[]).join(', '))+'</p><p>Declared allergens: '+esc((x.allergens||[]).join(', '))+'. '+esc(x.allergen_note)+'</p>'+table(['Recorded nutrient','Estimate'],Object.keys(r.productionCatalogue.coverage).map(k=>[esc(k.replaceAll('_',' ')),num(x.nutrition[k])]))+'<p>Unknown source values: '+esc(JSON.stringify(x.nutrition.unknown_nutrients||{}))+'</p><p>'+esc((x.nutrition_limitations||[]).join(' '))+'</p><p>Food safety: '+esc((x.food_safety||[]).join(' '))+'</p><p>Storage: '+esc(typeof x.storage==='object'?JSON.stringify(x.storage):x.storage)+'</p></details>').join('');
const original=r.originalObservedDay.days[0];
const html='<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Grub generated-week nutrition review · 23 October 2026</title><style>*{box-sizing:border-box}body{margin:0;background:#e7e3da;color:#050505;font:16px/1.55 system-ui,sans-serif;overflow-wrap:anywhere}main{max-width:1050px;margin:auto;padding:24px}header,section{background:#fff;border:1px solid #707762;border-radius:12px;padding:24px;margin-bottom:20px}header{border-top:8px solid #707762}h1,h2{line-height:1.2}h1{font-size:32px}h2{font-size:24px}a{color:#405139}table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:14px}td,th{border:1px solid #b5b9ae;text-align:left;padding:10px;vertical-align:top}th{background:#e7e3da}details{border-top:1px solid #b5b9ae;padding:16px 0}summary{font-weight:700;cursor:pointer;min-height:44px}code{font-size:12px}.note{border-left:5px solid #707762;padding:14px;background:#e7e3da}@media(max-width:600px){main{padding:10px}header,section{padding:16px}h1{font-size:26px}td,th{padding:7px;font-size:12px}}@media print{body{background:#fff}main{max-width:none;padding:0}section{break-inside:avoid}details{break-inside:avoid}}</style></head><body><main><header><p>SHIFT · GRUB · REVIEW EVIDENCE</p><h1>What does the generated week actually provide?</h1><p>23 October 2026. Technical nutrition evidence from the live recipe catalogue. Independent specialist assessment has not been performed.</p><p class="note"><strong>1,712 of 2,692 recipes have unknown fibre.</strong> Fibre totals are unknown on <strong>1,711 of 1,800 generated days</strong>. Unknown is not zero. The existing low-total engineering safeguard is live; it does not establish that a higher total is balanced or right for an individual.</p><p>The existing 17 October recipe-publication waiver is retained. This addendum concerns the current generated-day/week offer; it does not reopen that publication decision or create another task tracker.</p></header><section><h2>Evidence and limits</h2><p>360 plans across four styles, three durations and 30 deterministic seeds: 1,800 days. Recipes and publication authority were read using six read-only queries. No customer records were read and no member data was changed.</p><p>The original observed three-meal day totals <strong>'+num(original.kcal)+' kcal/person</strong>; fibre is unknown. Its source recipe identities are preserved. That day is now identified by the engineering hold.</p>'+coverage+matrix+'<p>Recipe estimates are not a complete nutrient profile: the currently recorded fields do not include salt or a full vitamin/mineral panel. The examples exclude snacks, drinks and other food. Passing the 1,200-kcal engineering trigger is not independent sign-off.</p></section><section><h2>Decisions for the reviewer</h2><ol>'+r.decisionsNeeded.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ol><p>Owner reviewer: Matt O’Brien (nominated) · review date: pending · decision: pending. No independent professional qualification or specialist approval is attested.</p><p>Review the day/week proposition alongside the original recipe review material, ingredient sources and real portion/cooking trials where required.</p></section>'+cases+'<section><h2>Exact example recipe contents ('+r.exampleRecipes.length+')</h2><p>Open a recipe to inspect its actual ingredients, method, serving basis, declared allergens and nutrient estimates. These snapshots support review and do not guarantee allergy suitability.</p>'+details+'</section><section><h2>Traceability</h2><p>Current serving source: <code>'+esc(r.sourceCommit)+'</code></p><p>Public recipe snapshot SHA-256: <code>'+esc(r.productionCatalogue.digest)+'</code></p><p>Existing review: '+esc(r.priorReview.title)+' · version '+esc(r.priorReview.version)+'. That historical pack records the owner waiver; it does not supply a performed independent nutrition review.</p><p>The original NHS Eatwell and NICE references remain in the project evidence. No personalised calorie or nutrient target is assigned in this document.</p></section></main></body></html>';
writeFileSync('release/Grub-Plan-Nutrition-Review-20261023.html',html);
console.log(JSON.stringify({bytes:Buffer.byteLength(html),exampleRecipes:r.exampleRecipes.length,fibreUnknownDays:r.matrix.fibreUnknownDays,independentReviewPerformed:false}));
